import{S3_CENTER}from'./center-registration.mjs';
import{HUB}from'../okpo-hub-native/registration.mjs';import{AJU}from'../aju-native/registration.mjs';import{dataRecord,footPair}from'../aju-native/support.mjs';import{matchesSourceRow}from'./source-row-variants.mjs';
const regions={hub:HUB,aju:AJU},owners=new WeakMap,grants=new WeakMap;export const S3_CONTACT_REVISION='S3_NATIVE_CONTACT_AUTHORITY_V1';const point=(region,id)=>region==='hub'&&id==='heal:S3'?S3_CENTER:regions[region]?.points.find(p=>p.pointId===id&&p.kind!=='warp');
export function isS3ContactRequest(region,id,a){const p=point(region,id),heal=p?.kind==='heal',trade=p?.pointId==='acquisition:TRADE_029_CICADA'&&Object.hasOwn(a??{},'tradeInstanceId'),v=dataRecord(a,heal?['type','transactionId']:trade?['type','tradeInstanceId']:['type']);return!!p&&!!v&&v.type===p.kind&&(!heal||typeof v.transactionId==='string'&&v.transactionId.length>0&&v.transactionId.length<=160)&&(!trade||typeof v.tradeInstanceId==='string'&&v.tradeInstanceId.length>0)}
export function createS3ContactAuthority({region,getWorld,readNative,getSignal,isPresented}={}){if(!regions[region]||[getWorld,readNative,getSignal,isPresented].some(f=>typeof f!=='function'))throw Error('S3_CONTACT_OWNER_REQUIRED');const token=Object.freeze({});owners.set(token,{region,getWorld,readNative,getSignal,isPresented});return token}export const isS3ContactAuthority=a=>owners.has(a);
function canonical(o,w,p){const s=w.snapshot(),r=regions[o.region];return s.position.scene===r.mapId&&s.world.mapId===r.mapId&&matchesSourceRow(w.adapter,p.pointId,w.definition.points[p.pointId])}
function read(o,p){const r=regions[o.region],n=dataRecord(o.readNative(),['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','state','phase','sessionEpoch','gameplayRevision']);if(!n||n.version!==1||n.sceneId!==r.sceneId||n.mapId!==r.mapId||n.revision!==r.revision||n.imageSHA!==r.image.sha256||n.maskSHA!==r.support.sha256||n.state!==0||n.phase!=='field'||n.gameplayRevision!==S3_CONTACT_REVISION||!Number.isSafeInteger(n.sessionEpoch)||n.sessionEpoch<1||!footPair(n.foot)||p.facing!==n.facing||!p.approachRows.some(([y,a,b])=>n.foot[1]===y&&n.foot[0]>=a&&n.foot[0]<b)||o.isPresented()!==true)return null;return{epoch:n.sessionEpoch,foot:[...n.foot],facing:n.facing}}
export function mintS3ContactGrant(a,w,id){const o=owners.get(a),p=o&&point(o.region,id);if(!o||o.getWorld()!==w||!p||!canonical(o,w,p))throw Error('S3_CONTACT_UNAVAILABLE');const n=read(o,p),signal=o.getSignal();if(!n)throw Error('S3_CONTACT_APPROACH');if(!(signal instanceof AbortSignal)||signal.aborted)throw Error('S3_CONTACT_LIFECYCLE');const token=Object.freeze({});grants.set(token,{a,w,p,n,signal});return token}
export function validateS3ContactGrant(g,w,id){try{const q=grants.get(g),o=q&&owners.get(q.a);if(!q||q.w!==w||!o||o.getWorld()!==w||q.signal.aborted||o.getSignal()!==q.signal||id!==undefined&&id!==q.p.pointId||!canonical(o,w,q.p))return false;const n=read(o,q.p);return!!n&&n.epoch===q.n.epoch&&n.facing===q.n.facing&&n.foot[0]===q.n.foot[0]&&n.foot[1]===q.n.foot[1]}catch{return false}}
export function assertS3ContactGrant(g,w){if(!validateS3ContactGrant(g,w))throw Error('S3_CONTACT_DRIFT')}export const revokeS3ContactGrant=g=>grants.delete(g);export function signalS3ContactGrant(g,w){assertS3ContactGrant(g,w);return grants.get(g).signal}
